    "content": "1985年记忆深处的长卷：那年夏天特别热，县城里的柏油路被晒得发软。下午三点大院里静悄悄的，只有知了在槐树上叫个不停。我和死党躲在平房里分一瓶冰镇汽水，收音机里正转播着《华语群星合唱《明天会更好》》的消息。那时候我们总觉得时间过得很慢，总以为长大是一件很遥远的事。如今一晃几十年过去，当年一起分汽水的朋友早已散落天涯，但那个蝉鸣阵阵的午后，依然是我记忆里最清澈的角落。",
    "reply": "时光如水流逝，但那些纯粹而滚烫的午后片段，永远是生命长河中最明亮的锚点。",
    "likes": 283,
    "pinType": "clip",
    "tilt": 1.8,
