    "author": "@卡带倒带王",
    "avatar": "🚲",
    "timestamp": "放学路上",
    "content": "1987年记忆深处的长卷：冬天下了一场罕见的大雪，整个老城白茫茫一片。晚自习教室里生着煤炉子，大家一边烤着馒头片一边讨论红高粱的各种细节。班主任推门进来没有批评我们，反而坐下来跟我们一起烤手聊天，讲起他年轻时的那些理想。窗外的雪静静地下着，炉火映红了每个人的脸庞。那一晚的温暖，治愈了我往后在漫长人生风雪中走过的很多个孤独时刻。",
    "reply": "炉火虽小，却能抵挡严寒；平凡的日子虽短，却能照亮行者的一生。",
