    "content": "1993年记忆深处的长卷：那年高考放榜那天，家里那部老式红色座机电话响个不停。老爸拿着铅笔在日记本上记下分数那一刻，平时极其严肃的他突然捂住脸哭出了声，老妈在厨房里擦着围裙跑出来抱住我们。窗外的阳光正好落在客厅那张全家福上。那一刻我终于明白，我们每一次往前迈出的一小步，背后都是父母默默托举一生的重量。",
