    "content": "那年夏天放学，和死党凑了零钱在老街吃冰棍，路过百货大楼看见《《同桌的你》与红磡摇滚中国乐势力》的大海报，两个人呆呆看了半小时。",
    "reply": "海报落了灰，但那个夏天的冰棍甜香，记了一辈子。",
    "likes": 228,
    "pinType": "pin",
    "tilt": 1.2,
