    "content": "那年夏天放学，和死党凑了零钱在老街吃冰棍，路过百货大楼看见《《武林外传》首播与同福客栈》的大海报，两个人呆呆看了半小时。",
    "reply": "海报落了灰，但那个夏天的冰棍甜香，记了一辈子。",
